            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Ce toit tranquille, où marchent des colombes, Entre les pins palpite, entre les tombes; Midi le juste y compose de feux La mer, la mer, toujours recommencée ! Ô récompense après une pensée Qu’un long regard sur le calme des dieux !", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le vent se lève ! … Il faut tenter de vivre ! L’air immense ouvre et referme mon livre", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Patience, patience, Patience dans l’azur ! Chaque atome de silence Est la chance d’un fruit mûr !", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Je n’aime pas trop les musées. Il y en a beaucoup d’admirables, il n’en est point de délicieux. Les idées de classement, de conservation et d’utilité publique, qui sont justes et claires, ont peu de rapport avec les délices.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L’Europe deviendra-t-elle ce qu’elle est en réalité, c’est-à-dire : un petit cap du continent asiatique, ou bien l’Europe restera-t-elle ce qu’elle paraît, c’est-à-dire : la partie précieuse de l’univers terrestre, la perle de la sphère, le cerveau d’un vaste corps ?", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Nous ne supportons plus la durée. Nous ne savons plus féconder l'ennui. Notre nature a horreur du vide, — ce vide sur lequel les esprits de jadis savaient peindre les images de leurs idéaux, leurs Idées, au sens de Platon.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Ce n'est qu'un jeu pour l'amateur de symétries historiques, c'est-à-dire imaginaires, que de démontrer que ces deux figures littéraires sont des figures semblables.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Dans les domaines de la création, qui sont aussi les domaines de l'orgueil, la nécessité de se distinguer est indivisible de l'existence même.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le poète se consacre et se consume donc à définir et à construire un langage dans le langage.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Mais un homme excité ne se paie pas de logique. Mon ami regardait mon calme comme un beau vase qui donne envie de le mettre en morceaux.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Nous autres, civilisations, nous savons maintenant que nous sommes mortelles.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "En vérité, il n’est pas de théorie qui ne soit un fragment, soigneusement préparé, de quelque autobiographie.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le moi est haïssable... mais il s'agit de celui des autres.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Celui qui n'a pas nos répugnances nous répugne.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Chacune des qualités d'un esprit apporte des chances particulières d'erreur à la représentation du réel. Si tu es vif, le lent t'échappe.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le mensonge et la crédulité s'accouplent et engendrent l'Opinion.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Les vilaines pensées viennent du cœur.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Nous ne pensons que par hasard aux circonstances permanentes de notre vie ; nous ne les percevons qu'au moment où elles s'altèrent tout à coup.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'accomplissement de nos désirs ne nous éloigne pas toujours de notre perte.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Une guerre dont l´issue n'a été due qu'a l'inégalité des puissances totales des adversaires est une guerre suspendue.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "La politique fut d'abord l'art d'empêcher les gens de se mêler de ce qui les regarde. À une époque suivante, on y adjoignit l'art de contraindre les gens à décider sur ce qu'ils n'entendent pas.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "L'historien fait pour le passé ce que la tireuse de cartes fait pour le futur. Mais la sorcière s'expose à une vérification et non l'historien.", Author = "Paul Valéry" },
