            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il est des hommes dont l'oreille, toute saine qu'elle est, ne distingue pas les sons d'avec les bruits.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Les petits faits inexpliqués contiennent toujours de quoi renverser toutes les explications des grands faits.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le réveil fait aux rêves une réputation qu'ils ne méritent pas.", Author = "Paul Valéry" },
