            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Dieu créa l'homme, et ne le trouvant pas assez seul, il lui donne une compagne pour lui faire mieux sentir sa solitude.", Author = "Paul Valéry" },
