            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Pamphlétaires, orateurs, violents, forcenés, qui vociférez, dites, ne sentez-vous jamais que tout homme qui crie est sur le point de faire semblant de crier ?", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Le plaisir qu'il y a à comprendre certains raisonnements délicats dispose l'esprit en faveur de leurs conclusions.", Author = "Paul Valéry" },
