            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Un homme absorbé dans la plus profonde méditation. Son visage est vide, rien n'est écrit par ses traits. Comment peut-on être si loin de ce que l'on a de plus près?", Author = "Paul Valéry" },
