            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il y a de la pauvreté d'esprit à être toujours d'accord avec soi-même.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il reste d’un homme ce que donnent à songer son nom et les œuvres qui font de ce nom un signe d’admiration, de haine ou d’indifférence.", Author = "Paul Valéry" },
