            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Il y eut une fois Quelqu’un qui pouvait regarder le même spectacle ou le même objet, tantôt comme l’eût regardé un peintre, et tantôt en naturaliste ; tantôt comme un physicien, et d’autres fois, comme un poète : et aucun de ces regards n’était superficiel.", Author = "Paul Valéry" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Valéry", Text = "Les recherches insensées sont parentes des découvertes imprévues.", Author = "Paul Valéry" },
